import{_ as e,o as r,c as o,am as n}from"./chunks/framework._FJXuPhs.js";const P=JSON.parse('{"title":"Spring学习_AOP","description":"","frontmatter":{"title":"Spring学习_AOP","excerpt":"Spring学习_AOP","date":"2023-12-05 16:40:34","updated":"2023-12-05 16:40:34"},"headers":[],"relativePath":"框架/框架 Spring家族/框架 Spring/Spring学习_AOP.md","filePath":"框架/框架 Spring家族/框架 Spring/Spring学习_AOP.md","lastUpdated":null}'),i={name:"框架/框架 Spring家族/框架 Spring/Spring学习_AOP.md"};function a(d,t,p,l,s,g){return r(),o("div",null,[...t[0]||(t[0]=[n('<h3 id="_1、什么是aop" tabindex="-1">1、什么是AOP <a class="header-anchor" href="#_1、什么是aop" aria-label="Permalink to &quot;1、什么是AOP&quot;">​</a></h3><p>AOP（Aspect-Oriented Programming:面向切面编程）是一种编程范式，通过在代码中横向插入关注点（如日志、事务），实现对应用程序模块化、可维护性和可重用性的提升。</p><p>AOP 切面编程涉及到的一些专业术语：</p><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>目标(Target)</td><td>被通知的对象</td></tr><tr><td>代理(Proxy)</td><td>向目标对象应用通知之后创建的代理对象</td></tr><tr><td>连接点(JoinPoint)</td><td>目标对象的所属类中，定义的所有方法均为连接点</td></tr><tr><td>切入点(Pointcut)</td><td>被切面拦截 / 增强的连接点（切入点一定是连接点，连接点不一定是切入点）</td></tr><tr><td>通知(Advice)</td><td>增强的逻辑 / 代码，也即拦截到目标对象的连接点之后要做的事情</td></tr><tr><td>切面(Aspect)</td><td>切入点(Pointcut)+通知(Advice)</td></tr><tr><td>Weaving(织入)</td><td>将通知应用到目标对象，进而生成代理对象的过程动作</td></tr></tbody></table><h3 id="_2、spring-aop-的实现" tabindex="-1">2、Spring AOP 的实现 <a class="header-anchor" href="#_2、spring-aop-的实现" aria-label="Permalink to &quot;2、Spring AOP 的实现&quot;">​</a></h3><p>Spring AOP基于动态代理实现，</p><ul><li>对于实现了接口的对象，使用JDK Proxy创建代理对象；</li><li>对于未实现接口的对象，使用Cglib生成被代理对象的子类。</li></ul><p>Spring AOP还集成了AspectJ，AspectJ是Java生态系统中最完整的AOP框架，拥有更多功能，特别在切面较多的情况下，选择AspectJ相比Spring AOP更为高效。</p><hr><p>Spring的AOP（面向切面编程）允许开发者定义横切关注点（如日志、事务管理等），这些关注点通常与业务逻辑的主流程解耦，可以跨越应用的多个点。AOP通过在运行时动态地将代码注入到指定位置来实现这一点，而这正是通过“代理”完成的。</p><p>实现AOP的方式主要有两种：</p><ol><li><strong>JDK动态代理</strong>：适用于那些实现了接口的对象。它通过反射机制在运行时创建代理对象，将横切逻辑织入到这些对象中。</li><li><strong>CGLIB代理</strong>：适用于没有实现接口的对象。它通过底层的字节码技术生成被代理对象的子类，并在子类中注入横切逻辑。</li></ol><hr><h4 id="动态代理" tabindex="-1">动态代理 <a class="header-anchor" href="#动态代理" aria-label="Permalink to &quot;动态代理&quot;">​</a></h4><p>介绍一下相关的功能</p><p>在 Java AOP （面向切面编程）中，动态代理是一种实现机制，它在运行时创建一个实现了一组接口的代理对象。这个代理对象可以在原有对象方法调用前后执行额外的操作（如日志记录、事务管理等），而无需修改原有对象的代码。这种机制主要通过两种方式实现：基于接口的 JDK 动态代理和基于类的代理（例如使用 CGLIB 或 ByteBuddy）。</p><blockquote><p>JDK 动态代理</p></blockquote><p>JDK 动态代理使用 <code>java.lang.reflect.Proxy</code> 类和 <code>java.lang.reflect.InvocationHandler</code> 接口实现。这种代理方式要求目标对象必须实现一个或多个接口。</p><p><strong>工作原理</strong></p><ol><li><strong>接口实现</strong>：动态代理类必须实现目标类的一个或多个接口。</li><li><strong>创建代理实例</strong>：通过 <code>Proxy.newProxyInstance</code> 方法创建代理实例。这个方法需要： <ul><li>类加载器（用于定义代理类）</li><li>一组接口（代理类将实现的接口）</li><li><code>InvocationHandler</code> 实现（所有方法调用都会转发到这个调用处理器）</li></ul></li><li><strong>方法调用</strong>：当代理实例的方法被调用时，调用会被转发到 <code>InvocationHandler</code> 的 <code>invoke</code> 方法。在 <code>invoke</code> 方法中，可以在调用目标方法之前或之后执行其他操作。</li></ol><p>通过 <code>point.getTarget()</code> 获取目标实例</p><p>在 AOP 框架中，当方法执行被拦截（如通过切点指定的方法），AOP 框架创建一个 <code>JoinPoint</code> 实例，该实例封装了有关当前方法调用的信息。<code>JoinPoint</code> 提供了 <code>getTarget()</code> 方法，该方法返回被代理的目标对象（原始对象），即使当前执行的是代理方法。因此，即使我们操作的是代理实例，我们也可以通过 <code>getTarget()</code> 访问到原始的目标类实例。</p><blockquote><p>CGLIB 动态代理</p></blockquote><p>CGLIB（Code Generation Library）是另一种动态代理方式，它不需要接口。CGLIB 通过继承目标类并在运行时生成子类来实现代理。</p><p>工作原理</p><ol><li><strong>子类生成</strong>：CGLIB 在运行时生成目标类的子类，并覆盖其方法以提供增强的功能。</li><li><strong>方法调用</strong>：当调用代理实例的方法时，实际上是调用由 CGLIB 生成的子类中的方法。在这些方法中，可以在调用实际的目标方法前后插入自定义的行为。</li></ol><p>使用场景与选择</p><ul><li><strong>JDK 动态代理</strong>适用于目标对象实现了接口的情况。由于只需代理接口方法，这种方式不会代理类的属性，通常性能较好。</li><li><strong>CGLIB 动态代理</strong>适用于目标对象没有实现任何接口的情况。它通过生成子类来实现代理，更为强大但通常比 JDK 动态代理略慢。</li></ul><p>总的来说，AOP 通过动态代理技术提供了一个非常强大的机制，允许开发者在不修改原始代码的情况下，增加额外的功能。通过 <code>point.getTarget()</code> 获取到的是代理调用中的原始对象，确保了即使在代理环境中，也能正确地处理业务逻辑。</p><hr><p>参考</p><ul><li><a href="https://www.pdai.tech/md/spring/spring-x-framework-aop.html" target="_blank" rel="noreferrer">https://www.pdai.tech/md/spring/spring-x-framework-aop.html</a></li><li><a href="https://javaguide.cn/system-design/framework/spring/spring-knowledge-and-questions-summary.html#spring-aop" target="_blank" rel="noreferrer">https://javaguide.cn/system-design/framework/spring/spring-knowledge-and-questions-summary.html#spring-aop</a></li></ul>',32)])])}const h=e(i,[["render",a]]);export{P as __pageData,h as default};
